    // SDRAMBASEADDR SDRAM DMA buffer base address (bits [30:0]).
    I2cV1I2CDMABASEADDRSDRAMBASEADDRPos = 0
    I2cV1I2CDMABASEADDRSDRAMBASEADDRMsk = 0x7fffffff << 0
