    // CMDQUEUEEMPTYLOC Number of empty locations in command queue.
    I3cV1I3CQUEUESTATUSLEVELCMDQUEUEEMPTYLOCPos = 0
    I3cV1I3CQUEUESTATUSLEVELCMDQUEUEEMPTYLOCMsk = 0xff << 0
